const CD51_LOGO_DATA='data:image/png;base64,';
function cd51ApplyLogo(root=document){if(!root)return;const fav=document.getElementById('cd51Favicon');if(fav)fav.href=CD51_LOGO_DATA;document.querySelectorAll('.cd51TopLogo').forEach(img=>img.src=CD51_LOGO_DATA);root.querySelectorAll?.('.sideBrand:not(.cd51Applied),.c44Brand:not(.cd51Applied)').forEach(el=>{el.classList.add('cd51Applied');el.innerHTML=`<img class="cd51SideLogo" src="${CD51_LOGO_DATA}" alt="Coach Di">`})}
cd51ApplyLogo();new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType===1)cd51ApplyLogo(n.matches?.('.sideBrand,.c44Brand')?n.parentElement:n)}))).observe(document.body,{childList:true,subtree:true});
